import React, { useEffect, useRef, useState } from 'react';
import api from '../services/api';

/*
  AdminCharts — Statistiques visuelles EduMatch
  ─────────────────────────────────────────────
  Toutes les données viennent de /api/admin/stats/charts (BDD réelle).

  Graphiques :
  1. Réservations par mois     — line chart (6 derniers mois, BDD réelle)
  2. Matières par domaine      — bar chart par onglet domaine (BDD réelle)
  3. Mode d'enseignement       — donut En ligne vs Présentiel (BDD réelle)
  4. Statut des professeurs    — donut Validés/Attente/Refusés (BDD réelle)
*/

// ── Chargement dynamique Chart.js ───────────────────────────────
function loadChart() {
  return new Promise(resolve => {
    if (window.Chart) { resolve(window.Chart); return; }
    const s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js';
    s.onload = () => resolve(window.Chart);
    document.head.appendChild(s);
  });
}

function useChart(ref, buildFn, deps) {
  const inst = useRef(null);
  useEffect(() => {
    if (!ref.current) return;
    loadChart().then(Chart => {
      if (inst.current) inst.current.destroy();
      inst.current = new Chart(ref.current.getContext('2d'), buildFn(Chart));
    });
    return () => { if (inst.current) inst.current.destroy(); };
  }, deps); // eslint-disable-line
}

// ── Palette de couleurs cohérente ───────────────────────────────
const PAL = ['#6c63ff','#ff6584','#43e97b','#38bdf8','#f59e0b','#a78bfa','#34d399','#fb923c'];

// ════════════════════════════════════════════
//  1. LINE CHART — Réservations par mois
// ════════════════════════════════════════════
function LineReservations({ data }) {
  const ref = useRef(null);
  useChart(ref, Chart => ({
    type: 'line',
    data: {
      labels: data.map(d => d.mois),
      datasets: [{
        label: 'Réservations',
        data:  data.map(d => d.total),
        borderColor:     '#6c63ff',
        backgroundColor: 'rgba(108,99,255,0.1)',
        borderWidth: 2.5,
        fill: true,
        tension: 0.4,
        pointBackgroundColor: '#6c63ff',
        pointRadius: 5,
        pointHoverRadius: 8,
      }],
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#1e293b', titleColor: '#94a3b8',
          bodyColor: '#fff', borderColor: '#334155', borderWidth: 1,
          callbacks: { label: c => ` ${c.parsed.y} réservation${c.parsed.y > 1 ? 's' : ''}` },
        },
      },
      scales: {
        x: { grid: { color: 'rgba(255,255,255,0.04)' }, ticks: { color: 'var(--text2, #64748b)', font: { size: 11 } } },
        y: { beginAtZero: true, grid: { color: 'rgba(255,255,255,0.04)' }, ticks: { color: 'var(--text2, #64748b)', font: { size: 11 }, stepSize: 1 } },
      },
    },
  }), [JSON.stringify(data)]);
  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════
//  2. BAR CHART — Matières d'un domaine
// ════════════════════════════════════════════
function BarMatieres({ matieres, metric }) {
  const ref = useRef(null);
  useChart(ref, Chart => ({
    type: 'bar',
    data: {
      labels: matieres.map(m => m.matiere),
      datasets: [{
        label: metric === 'nb_profs' ? 'Formateurs' : 'Réservations',
        data:  matieres.map(m => m[metric]),
        backgroundColor: matieres.map((_, i) => PAL[i % PAL.length] + 'cc'),
        borderColor:     matieres.map((_, i) => PAL[i % PAL.length]),
        borderWidth: 1.5,
        borderRadius: 6,
      }],
    },
    options: {
      indexAxis: 'y',
      responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#1e293b', titleColor: '#94a3b8',
          bodyColor: '#fff', borderColor: '#334155', borderWidth: 1,
        },
      },
      scales: {
        x: { beginAtZero: true, grid: { color: 'rgba(255,255,255,0.04)' }, ticks: { color: 'var(--text2, #64748b)', font: { size: 11 }, stepSize: 1 } },
        y: { grid: { display: false }, ticks: { color: 'var(--text, #e2e8f0)', font: { size: 12 } } },
      },
    },
  }), [JSON.stringify(matieres), metric]);
  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════
//  3. DONUT — Mode d'enseignement
// ════════════════════════════════════════════
function DonutModes({ data }) {
  const ref = useRef(null);
  useChart(ref, Chart => ({
    type: 'doughnut',
    data: {
      labels: data.map(d => d.label),
      datasets: [{
        data:            data.map(d => d.val),
        backgroundColor: ['#6c63ff', '#43e97b'],
        borderColor:     'var(--surface, #1e293b)',
        borderWidth: 3,
        hoverOffset: 8,
      }],
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      cutout: '68%',
      plugins: {
        legend: {
          position: 'bottom',
          labels: { color: 'var(--text2, #94a3b8)', font: { size: 11 }, padding: 14, usePointStyle: true },
        },
        tooltip: {
          backgroundColor: '#1e293b', bodyColor: '#fff', borderColor: '#334155', borderWidth: 1,
          callbacks: { label: c => ` ${c.label} : ${c.parsed} prof${c.parsed > 1 ? 's' : ''}` },
        },
      },
    },
  }), [JSON.stringify(data)]);
  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════
//  4. DONUT — Statut des professeurs
// ════════════════════════════════════════════
function DonutStatut({ data }) {
  const ref = useRef(null);
  useChart(ref, Chart => ({
    type: 'doughnut',
    data: {
      labels: data.map(d => d.label),
      datasets: [{
        data:            data.map(d => d.val),
        backgroundColor: ['#43e97b', '#f59e0b', '#ef4444'],
        borderColor:     'var(--surface, #1e293b)',
        borderWidth: 3,
        hoverOffset: 8,
      }],
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      cutout: '68%',
      plugins: {
        legend: {
          position: 'bottom',
          labels: { color: 'var(--text2, #94a3b8)', font: { size: 11 }, padding: 14, usePointStyle: true },
        },
        tooltip: {
          backgroundColor: '#1e293b', bodyColor: '#fff', borderColor: '#334155', borderWidth: 1,
          callbacks: { label: c => ` ${c.label} : ${c.parsed} prof${c.parsed > 1 ? 's' : ''}` },
        },
      },
    },
  }), [JSON.stringify(data)]);
  return <canvas ref={ref} />;
}

// ════════════════════════════════════════════
//  CARTE CONTENEUR
// ════════════════════════════════════════════
function Card({ icon, title, subtitle, height = 240, children, style = {} }) {
  return (
    <div style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 18, padding: '20px 22px', display: 'flex', flexDirection: 'column', gap: 14, ...style }}>
      <div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
          <span style={{ fontSize: '1.1rem' }}>{icon}</span>
          <span style={{ fontFamily: 'Syne,sans-serif', fontWeight: 700, fontSize: '.95rem', color: 'var(--text)' }}>{title}</span>
        </div>
        {subtitle && <div style={{ fontSize: '.72rem', color: subtitle.startsWith('✅') ? '#43e97b' : subtitle.startsWith('⚠️') ? '#f59e0b' : 'var(--text2)' }}>{subtitle}</div>}
      </div>
      <div style={{ height, position: 'relative', minHeight: height }}>
        {children}
      </div>
    </div>
  );
}

function Empty({ msg = 'Aucune donnée' }) {
  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 8, color: 'var(--text2)', fontSize: '.82rem' }}>
      <span style={{ fontSize: '2rem' }}>📭</span>{msg}
    </div>
  );
}

// ════════════════════════════════════════════
//  COMPOSANT PRINCIPAL
// ════════════════════════════════════════════
export default function AdminCharts({ stats = {} }) {
  const [data, setData]         = useState(null);
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState(null);
  const [domainIdx, setDomainIdx] = useState(0);  // Onglet domaine actif
  const [metric, setMetric]     = useState('nb_profs'); // nb_profs ou nb_resa

  useEffect(() => {
    api.get('/api/admin/stats/charts')
      .then(res => {
        setData(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error('[AdminCharts]', err);
        setError('Impossible de charger les statistiques.');
        setLoading(false);
      });
  }, []);

  if (loading) return (
    <div style={{ padding: 40, textAlign: 'center', color: 'var(--text2)', fontSize: '.9rem' }}>
      <div style={{ fontSize: '2rem', marginBottom: 8 }}>📊</div>
      Chargement des statistiques…
    </div>
  );

  if (error) return (
    <div style={{ padding: 24, textAlign: 'center', color: '#ef4444', fontSize: '.85rem' }}>
      ❌ {error}
    </div>
  );

  const {
    reservations_par_mois = [],
    matieres_par_domaine  = [],
    modes_enseignement    = [],
    statut_profs          = [],
  } = data;

  // Domaine actif
  const domaineActif   = matieres_par_domaine[domainIdx] || null;
  const totalResa      = reservations_par_mois.reduce((a, b) => a + b.total, 0);
  const hasResa        = totalResa > 0;
  const modesFiltered  = modes_enseignement.filter(m => m.val > 0);
  const statutFiltered = statut_profs.filter(s => s.val > 0);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>

      {/* Titre */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <div style={{ width: 4, height: 24, background: 'linear-gradient(180deg,#6c63ff,#ff6584)', borderRadius: 2 }} />
        <div>
          <h2 style={{ fontFamily: 'Syne,sans-serif', fontWeight: 800, fontSize: '1.1rem', margin: 0, color: 'var(--text)' }}>
            Statistiques & Analyses
          </h2>
          <p style={{ fontSize: '.73rem', color: 'var(--text2)', margin: 0 }}>
            Données en temps réel depuis la base de données EduMatch
          </p>
        </div>
      </div>

      {/* ── LIGNE 1 : Réservations/mois + Matières par domaine ── */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>

        {/* Graphique 1 — Réservations par mois */}
        <Card
          icon="📈"
          title="Réservations par mois"
          subtitle={hasResa
            ? `✅ Données réelles — ${totalResa} réservation${totalResa > 1 ? 's' : ''} au total`
            : '⚠️ Aucune réservation enregistrée pour le moment'}
          height={250}
        >
          {reservations_par_mois.length > 0
            ? <LineReservations data={reservations_par_mois} />
            : <Empty msg="Aucune réservation" />}
        </Card>

        {/* Graphique 2 — Matières par domaine */}
        <Card
          icon="📚"
          title="Matières par domaine"
          subtitle={domaineActif
            ? `✅ Domaine : ${domaineActif.domaine} — ${domaineActif.matieres.length} matière${domaineActif.matieres.length > 1 ? 's' : ''}`
            : '⚠️ Aucun domaine avec des formateurs enregistrés'}
          height={250}
          style={{ overflow: 'visible' }}
        >
          {/* Onglets domaines */}
          {matieres_par_domaine.length > 0 && (
            <div style={{ position: 'absolute', top: -52, left: 0, right: 0, display: 'flex', gap: 6, flexWrap: 'wrap' }}>
              {matieres_par_domaine.map((d, i) => (
                <button key={i} onClick={() => setDomainIdx(i)}
                  style={{
                    padding: '4px 12px', fontSize: '.72rem', fontWeight: 600, borderRadius: 20, cursor: 'pointer', border: 'none',
                    background: i === domainIdx ? '#6c63ff' : 'var(--surface2)',
                    color:      i === domainIdx ? '#fff' : 'var(--text2)',
                    transition: 'all .2s',
                  }}
                >
                  {d.domaine}
                </button>
              ))}
              {/* Toggle métrique */}
              <div style={{ marginLeft: 'auto', display: 'flex', gap: 4 }}>
                {[['nb_profs', '👨‍🏫 Formateurs'], ['nb_resa', '📅 Réservations']].map(([k, l]) => (
                  <button key={k} onClick={() => setMetric(k)}
                    style={{ padding: '4px 10px', fontSize: '.68rem', fontWeight: 600, borderRadius: 20, cursor: 'pointer', border: 'none', background: metric === k ? '#ff6584' : 'var(--surface2)', color: metric === k ? '#fff' : 'var(--text2)', transition: 'all .2s' }}
                  >
                    {l}
                  </button>
                ))}
              </div>
            </div>
          )}

          {domaineActif && domaineActif.matieres.length > 0
            ? <BarMatieres matieres={domaineActif.matieres} metric={metric} />
            : <Empty msg="Aucune matière avec des formateurs" />}
        </Card>
      </div>

      {/* ── LIGNE 2 : 2 donuts + KPIs ── */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 16 }}>

        {/* Graphique 3 — Mode d'enseignement */}
        <Card
          icon="🌐"
          title="Mode d'enseignement"
          subtitle={modesFiltered.length > 0
            ? `✅ ${modesFiltered.reduce((a, b) => a + b.val, 0)} formateur${modesFiltered.reduce((a, b) => a + b.val, 0) > 1 ? 's' : ''} validés`
            : '⚠️ Aucun formateur validé'}
          height={210}
        >
          {modesFiltered.length > 0
            ? <DonutModes data={modesFiltered} />
            : <Empty msg="Aucun formateur validé" />}
        </Card>

        {/* Graphique 4 — Statut des professeurs */}
        <Card
          icon="👨‍🏫"
          title="Statut des formateurs"
          subtitle={`✅ Données réelles — ${statutFiltered.reduce((a, b) => a + b.val, 0)} profil${statutFiltered.reduce((a, b) => a + b.val, 0) > 1 ? 's' : ''} total`}
          height={210}
        >
          {statutFiltered.length > 0
            ? <DonutStatut data={statutFiltered} />
            : <Empty msg="Aucun profil enregistré" />}
        </Card>

        {/* KPIs textuels */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {[
            {
              icon: '🏆', label: 'Taux de validation',
              val: (() => {
                const total = statut_profs.reduce((a, b) => a + b.val, 0);
                const val   = statut_profs.find(s => s.label === 'Validés')?.val || 0;
                return total > 0 ? Math.round((val / total) * 100) + '%' : '—';
              })(),
              color: '#43e97b',
            },
            {
              icon: '📅', label: 'Réservations ce mois',
              val: stats.reservations_mois ?? reservations_par_mois[5]?.total ?? 0,
              color: '#6c63ff',
            },
            {
              icon: '⏳', label: 'Profils en attente',
              val: stats.en_attente ?? statut_profs.find(s => s.label === 'En attente')?.val ?? 0,
              color: '#f59e0b',
            },
            {
              icon: '📋', label: 'Demandes matières',
              val: stats.demandes_matieres_pending ?? 0,
              color: '#38bdf8',
            },
          ].map((kpi, i) => (
            <div key={i} style={{
              background: 'var(--surface)', border: '1px solid var(--border)',
              borderRadius: 14, padding: '12px 16px',
              display: 'flex', alignItems: 'center', gap: 12, flex: 1,
            }}>
              <div style={{ width: 36, height: 36, borderRadius: 10, background: kpi.color + '18', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1rem', flexShrink: 0 }}>
                {kpi.icon}
              </div>
              <div>
                <div style={{ fontFamily: 'Syne,sans-serif', fontWeight: 800, fontSize: '1.2rem', color: kpi.color, lineHeight: 1 }}>
                  {kpi.val}
                </div>
                <div style={{ fontSize: '.7rem', color: 'var(--text2)', marginTop: 3 }}>{kpi.label}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
